def func_test_upload_non_image_format(app: AppInstance) -> bool:
    """Upload a plain text file expecting a 4xx rejection."""
    board = "BoardD"
    url = f"http://localhost:{app.port}/photos"
    files = {"file": ("notanimage.txt", b"this is plain text, not an image", "text/plain")}
    data = {"board": board}
    resp = requests.post(url, files=files, data=data)
    if not _is_client_error(resp.status_code):
        app.logger.warning(
            "Expected client error for non-image upload, got %d %s",
            resp.status_code,
            resp.reason,
        )
        return False
    app.logger.info("Non-image upload correctly resulted in %d", resp.status_code)
    return True
